
// Exact associative canonical XOR/AND coefficient DAG. Nodes remain input-only.
#[derive(Clone,Copy)]struct Expr{kind:u8,a:u32,b:u32,random:bool}
struct Dag{nodes:Vec<Expr>,binary_cache:std::collections::HashMap<(u8,u32,u32),u32>,xor_terms:Vec<std::sync::Arc<[u32]>>,and_terms:Vec<std::sync::Arc<[u32]>>,xor_cache:std::collections::HashMap<std::sync::Arc<[u32]>,u32>,and_cache:std::collections::HashMap<std::sync::Arc<[u32]>,u32>}
impl Dag{
 fn new()->Self{Self{nodes:vec![Expr{kind:0,a:0,b:0,random:false},Expr{kind:1,a:0,b:0,random:false}],binary_cache:std::collections::HashMap::new(),xor_terms:Vec::new(),and_terms:Vec::new(),xor_cache:std::collections::HashMap::new(),and_cache:std::collections::HashMap::new()}}
 fn binary_opaque(&mut self,kind:u8,a:u32,b:u32)->u32{let(a,b)=if a<=b{(a,b)}else{(b,a)};let key=(kind,a,b);if let Some(id)=self.binary_cache.get(&key){return *id;}let id=self.nodes.len().try_into().unwrap();self.nodes.push(Expr{kind,a,b,random:self.nodes[a as usize].random||self.nodes[b as usize].random});self.binary_cache.insert(key,id);id}
 fn conjunction_implied(&self,id:u32,factors:&[u32])->bool{let mut pending=vec![id];let mut budget=2048;while let Some(v)=pending.pop(){if factors.binary_search(&v).is_ok(){continue;}if budget==0{return false;}budget-=1;let n=self.nodes[v as usize];if n.kind==6{pending.extend_from_slice(&self.and_terms[n.a as usize]);}else if n.kind==4{pending.push(n.a);pending.push(n.b);}else{return false;}}true}
 fn variable(&mut self,random:bool)->u32{let id=self.nodes.len().try_into().unwrap();self.nodes.push(Expr{kind:2,a:id,b:0,random});id}
 fn complementary(&self,a:u32,b:u32)->bool{self.complement_id(a)==Some(b)}
 fn complement_id(&self,id:u32)->Option<u32>{if id<2{return Some(1-id);}let n=self.nodes[id as usize];if n.kind==3&&(n.a==1||n.b==1){return Some(if n.a==1{n.b}else{n.a});}if let Some(v)=self.binary_cache.get(&(3,1,id)){return Some(*v);}if n.kind==5{let terms=&self.xor_terms[n.a as usize];if terms[0]==1{let rest=&terms[1..];return if rest.len()==1{Some(rest[0])}else{self.xor_cache.get(rest).copied()};}let mut key=Vec::with_capacity(terms.len()+1);key.push(1);key.extend_from_slice(terms);self.xor_cache.get(key.as_slice()).copied()}else{self.xor_cache.get([1,id].as_slice()).copied()}}
 fn has_and_factor(&self,expr:u32,factor:u32)->bool{let n=self.nodes[expr as usize];(n.kind==6&&self.and_terms[n.a as usize].binary_search(&factor).is_ok())||(n.kind==4&&(n.a==factor||n.b==factor))}
 fn xor(&mut self,a:u32,b:u32)->u32{if a==b{return 0;}if a==0{return b;}if b==0{return a;}let an=self.nodes[a as usize];let bn=self.nodes[b as usize];if an.kind==3{if an.a==b{return an.b;}if an.b==b{return an.a;}}if bn.kind==3{if bn.a==a{return bn.b;}if bn.b==a{return bn.a;}}let na=self.nodes[a as usize];let nb=self.nodes[b as usize];let aa=if na.kind==5{self.xor_terms[na.a as usize].as_ref()}else{std::slice::from_ref(&a)};let bb=if nb.kind==5{self.xor_terms[nb.a as usize].as_ref()}else{std::slice::from_ref(&b)};let mut out=Vec::with_capacity(aa.len()+bb.len());let(mut i,mut j)=(0,0);while i<aa.len()||j<bb.len(){if i<aa.len()&&(j==bb.len()||aa[i]<bb[j]){out.push(aa[i]);i+=1;}else if j<bb.len()&&(i==aa.len()||bb[j]<aa[i]){out.push(bb[j]);j+=1;}else{i+=1;j+=1;}}if out.is_empty(){return 0;}if out.len()==1{return out[0];}if out.len()>128{return self.binary_opaque(3,a,b);}if let Some(id)=self.xor_cache.get(out.as_slice()){return *id;}let random=out.iter().any(|i|self.nodes[*i as usize].random);let terms:std::sync::Arc<[u32]>=out.into();let index=self.xor_terms.len().try_into().unwrap();let id=self.nodes.len().try_into().unwrap();self.xor_terms.push(terms.clone());self.xor_cache.insert(terms,id);self.nodes.push(Expr{kind:5,a:index,b:0,random});id}
 fn not(&mut self,a:u32)->u32{self.xor(1,a)}
 fn and(&mut self,a:u32,b:u32)->u32{if a==0||b==0{return 0;}if a==1{return b;}if b==1||a==b{return a;}if self.complementary(a,b){return 0;}if self.has_and_factor(a,b){return a;}if self.has_and_factor(b,a){return b;}let na=self.nodes[a as usize];let nb=self.nodes[b as usize];let aa=if na.kind==6{self.and_terms[na.a as usize].as_ref()}else{std::slice::from_ref(&a)};let bb=if nb.kind==6{self.and_terms[nb.a as usize].as_ref()}else{std::slice::from_ref(&b)};let mut out=Vec::with_capacity(aa.len()+bb.len());let(mut i,mut j)=(0,0);while i<aa.len()||j<bb.len(){if i<aa.len()&&(j==bb.len()||aa[i]<bb[j]){out.push(aa[i]);i+=1;}else if j<bb.len()&&(i==aa.len()||bb[j]<aa[i]){out.push(bb[j]);j+=1;}else{out.push(aa[i]);i+=1;j+=1;}}for x in&out{if let Some(c)=self.complement_id(*x){if out.binary_search(&c).is_ok(){return 0;}if self.conjunction_implied(c,&out){return 0;}}}if out.len()==1{return out[0];}if out.len()>128{return self.binary_opaque(4,a,b);}if let Some(id)=self.and_cache.get(out.as_slice()){return *id;}let random=out.iter().any(|i|self.nodes[*i as usize].random);let terms:std::sync::Arc<[u32]>=out.into();let index=self.and_terms.len().try_into().unwrap();let id=self.nodes.len().try_into().unwrap();self.and_terms.push(terms.clone());self.and_cache.insert(terms,id);self.nodes.push(Expr{kind:6,a:index,b:0,random});id}
}
